-- ════════════════════════════════════════════════════════════════════════════
-- scripts/db-seed.sql — 本地開發 / CI 示例資料種子（SCHEMA §Seed Data 之同步來源）
--   「此 Seed Data 同步作為 docs/db/seed.sql 來源」(SCHEMA §Seed Data)。
-- Generated by gencode[platform-db-seed].
--
-- 與 migrations/V011 的關係：
--   * V011（版本化遷移，所有環境）只含「環境無關的參考目錄 / 契約」種子（無 PII / 無假帳號）。
--   * 本檔（dev/CI ONLY，非遷移鏈）額外提供示例帳號 / 錢包 / 權益 / 經營史 / 排行 / 存檔 /
--     feature flag 示例等「含假資料」的開發用資料集，故預設拒絕於 production 執行。
--
-- 冪等（EDD §Idempotent，Review #3「run twice row count 一致」）：
--   先 reset 示例資料（cleanup 路徑，Anti-Fake #6），再重新插入；參考目錄以自然鍵 upsert。
-- 執行前提：migrations V001–V012 已套用。INSERT 順序滿足 FK 依賴（catalog/parent 先）。
--
-- 用法（環境隔離，Review #6 — production 預設拒絕；需指定非 production 環境才執行）：
--   psql -v ON_ERROR_STOP=1 -c "SET yocat.seed_env='dev';" -f scripts/db-seed.sql
--   或  PGOPTIONS="-c yocat.seed_env=dev" psql -v ON_ERROR_STOP=1 -f scripts/db-seed.sql
--   （允許值：local / dev / ci / test；未設定或其它值 → 中止，保護 production）
-- ════════════════════════════════════════════════════════════════════════════

-- ── 環境閘：未指定非 production 環境即中止（fail-safe，預設拒絕）────────────────────
DO $guard$
DECLARE env text := lower(coalesce(current_setting('yocat.seed_env', true), ''));
BEGIN
  IF env NOT IN ('local', 'dev', 'ci', 'test') THEN
    RAISE EXCEPTION
      'db-seed refused (production fail-safe): set a non-production env first, e.g. SET yocat.seed_env = ''dev''; (got: %)',
      coalesce(nullif(env, ''), '<unset>');
  END IF;
  RAISE NOTICE 'db-seed running against env=%', env;
END
$guard$;

BEGIN;

